1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.time.temporal.ChronoUnit;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.Objects;
21	
22	/**
23	 * Maps Owner &amp; OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /**
29	     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
30	     * already been created on the same registration date.
31	     */
32	    private static final int BULK_SIGNUP_THRESHOLD = 80;
33	
34	    @Autowired
35	    protected ClinicService clinicService;
36	
37	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
38	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
39	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
40	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
41	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
42	    @Mapping(target = "locality", expression = "java(locality(owner))")
43	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
44	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
45	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
46	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
47	    public abstract OwnerDto toOwnerDto(Owner owner);
48	
49	    /**
50	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
51	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
52	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
53	     * the registration date (against which the age is measured) is absent.
54	     */
55	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
56	        LocalDate birthDate = owner.getBirthDate();
57	        LocalDate registrationDate = owner.getRegistrationDate();
58	        if (birthDate == null || registrationDate == null) {
59	            return null;
60	        }
61	        int age = Period.between(birthDate, registrationDate).getYears();
62	        if (age < 18) {
63	            return OwnerDto.AgeBandEnum.MINOR;
64	        }
65	        if (age < 65) {
66	            return OwnerDto.AgeBandEnum.ADULT;
67	        }
68	        return OwnerDto.AgeBandEnum.SENIOR;
69	    }
70	
71	    /**
72	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
73	     * longest first so the correct code is matched before a shorter prefix of it. Australia
74	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
75	     * endpoint normalizes against.
76	     */
77	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
78	
79	    /**
80	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
81	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
82	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
83	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
84	     */
85	    protected String telephoneDisplay(Owner owner) {
86	        String telephone = owner.getTelephone();
87	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
88	            return telephone;
89	        }
90	        String digits = telephone.substring(1);
